package net.officefloor.hq.app.setting;

/** The body of the settings being saved, as typed: the clerk limit (blank: no limit) and the floor, the terms and the late percent (each null or blank: left as it is), and the policy date (null: left as it is; blank: none, so the sheet's today), and the period numbering from-date (null: left as it is; blank: off), and the cap, the proof threshold and the note threshold (each null: left as it is; blank: none), and the grace days (null: left as it is; blank: off), and the entry date (null: left as it is; blank: off, so the sheet's today), and the terms of a grade's own, by grade (each left out, null or blank: left as it is), and the grace days of a grade, by grade (each left out or null: left as it is; blank: none), and the from-date (yyyy-mm-dd) each dated setting saved is recorded from, by setting key (left out or blank: the sheet's today), and the roles each action is permitted to, by action, as a comma separated list (left out or null: left as it is; blank: the standing rule), and the proof threshold of a grade, by grade (each left out or null: left as it is; blank: none, so the sheet's), and the pot (null: left as it is; blank: none), and the parent sheet's id (null: left as it is; blank: none), and the fiscal year start month (null or blank: left as it is), and the alert threshold (null: left as it is; blank: off), and the rounding mode (null: left as it is; blank: none, so the policy date decides), and the review threshold (null: left as it is; blank: none), and the escalation gap in days (null: left as it is; blank: off), and the review SLA in days (null: left as it is; blank: none), and the proof kinds, comma separated (null: left as it is; blank: none), and the default grade (null: left as it is; blank: none, so A), and the clerk limit of a grade, by grade (each left out or null: left as it is; blank: none, so the sheet's), and the mid and high score thresholds (each null: left as it is; blank: none), and the maximum of open claims per person (null: left as it is; blank: none). */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String cap, String proofThreshold, String graceDays, String noteThreshold, String entryDate,
        java.util.Map<String, String> gradeTerms, java.util.Map<String, String> gradeGrace, java.util.Map<String, String> from, java.util.Map<String, String> perms,
        java.util.Map<String, String> gradeProof, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade,
        java.util.Map<String, String> gradeClerkLimit, String scoreMid, String scoreHigh, String scoreLog, String maxOpen) {
}
